/*!
FullCalendar Minimal v6.1.8 - Offline Version
Provides basic month view calendar functionality
*/
var FullCalendar = (function() {
  'use strict';

  function Calendar(el, options) {
    this.el = el;
    this.options = options || {};
    this.events = options.events || [];
    this.currentDate = new Date();
  }

  Calendar.prototype.render = function() {
    this.el.innerHTML = '';
    this.el.className = 'fc fc-media-screen fc-direction-ltr';
    
    var container = document.createElement('div');
    container.className = 'fc-view-harness';
    
    // Toolbar
    var toolbar = this.createToolbar();
    container.appendChild(toolbar);
    
    // Calendar grid
    var grid = this.createMonthGrid();
    container.appendChild(grid);
    
    this.el.appendChild(container);
  };

  Calendar.prototype.createToolbar = function() {
    var self = this;
    var toolbar = document.createElement('div');
    toolbar.className = 'fc-toolbar';
    
    // Navigation buttons
    var navGroup = document.createElement('div');
    navGroup.className = 'fc-button-group';
    
    var prevBtn = document.createElement('button');
    prevBtn.className = 'fc-button fc-button-primary';
    prevBtn.innerHTML = '&lt;';
    prevBtn.onclick = function() {
      self.currentDate.setMonth(self.currentDate.getMonth() - 1);
      self.render();
    };
    
    var nextBtn = document.createElement('button');
    nextBtn.className = 'fc-button fc-button-primary';
    nextBtn.innerHTML = '&gt;';
    nextBtn.onclick = function() {
      self.currentDate.setMonth(self.currentDate.getMonth() + 1);
      self.render();
    };
    
    var todayBtn = document.createElement('button');
    todayBtn.className = 'fc-button fc-button-primary';
    todayBtn.textContent = 'Today';
    todayBtn.onclick = function() {
      self.currentDate = new Date();
      self.render();
    };
    
    navGroup.appendChild(prevBtn);
    navGroup.appendChild(nextBtn);
    
    // Title
    var title = document.createElement('h2');
    title.className = 'fc-toolbar-title';
    var months = ['January', 'February', 'March', 'April', 'May', 'June', 
                  'July', 'August', 'September', 'October', 'November', 'December'];
    title.textContent = months[this.currentDate.getMonth()] + ' ' + this.currentDate.getFullYear();
    
    toolbar.appendChild(navGroup);
    toolbar.appendChild(title);
    toolbar.appendChild(todayBtn);
    
    return toolbar;
  };

  Calendar.prototype.createMonthGrid = function() {
    var grid = document.createElement('div');
    grid.className = 'fc-scrollgrid';
    
    var table = document.createElement('table');
    table.style.width = '100%';
    
    // Header row (days of week)
    var thead = document.createElement('thead');
    var headerRow = document.createElement('tr');
    var days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    days.forEach(function(day) {
      var th = document.createElement('th');
      th.className = 'fc-col-header-cell';
      th.textContent = day;
      headerRow.appendChild(th);
    });
    thead.appendChild(headerRow);
    table.appendChild(thead);
    
    // Body (calendar days)
    var tbody = document.createElement('tbody');
    var firstDay = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth(), 1);
    var lastDay = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() + 1, 0);
    var startDay = firstDay.getDay();
    var totalDays = lastDay.getDate();
    
    var today = new Date();
    var currentDay = 1;
    var started = false;
    
    for (var week = 0; week < 6; week++) {
      if (currentDay > totalDays) break;
      
      var row = document.createElement('tr');
      
      for (var dayOfWeek = 0; dayOfWeek < 7; dayOfWeek++) {
        var cell = document.createElement('td');
        cell.className = 'fc-daygrid-day';
        
        if (!started && dayOfWeek === startDay) {
          started = true;
        }
        
        if (started && currentDay <= totalDays) {
          // Check if today
          if (today.getDate() === currentDay && 
              today.getMonth() === this.currentDate.getMonth() &&
              today.getFullYear() === this.currentDate.getFullYear()) {
            cell.classList.add('fc-day-today');
          }
          
          var dayTop = document.createElement('div');
          dayTop.className = 'fc-daygrid-day-top';
          var dayNum = document.createElement('a');
          dayNum.className = 'fc-daygrid-day-number';
          dayNum.textContent = currentDay;
          dayTop.appendChild(dayNum);
          cell.appendChild(dayTop);
          
          // Events container
          var eventsContainer = document.createElement('div');
          eventsContainer.className = 'fc-daygrid-day-events';
          
          // Find events for this day
          var cellDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth(), currentDay);
          var dayEvents = this.getEventsForDay(cellDate);
          var self = this;
          
          dayEvents.forEach(function(event) {
            var eventEl = document.createElement('a');
            eventEl.className = 'fc-event fc-h-event';
            eventEl.href = '#';
            eventEl.innerHTML = '<span class="fc-event-title">' + (event.title || 'Event') + '</span>';
            eventEl.onclick = function(e) {
              e.preventDefault();
              if (self.options.eventClick) {
                self.options.eventClick({ event: event });
              }
              if (self.options.eventDidMount) {
                // Navigate to event detail if id exists
                if (event.id) {
                  window.location.href = '/event/' + event.id;
                }
              }
            };
            eventsContainer.appendChild(eventEl);
          });
          
          cell.appendChild(eventsContainer);
          currentDay++;
        } else {
          cell.classList.add('fc-day-other');
        }
        
        row.appendChild(cell);
      }
      
      tbody.appendChild(row);
    }
    
    table.appendChild(tbody);
    grid.appendChild(table);
    
    return grid;
  };

  Calendar.prototype.getEventsForDay = function(date) {
    var self = this;
    return this.events.filter(function(event) {
      var eventStart = new Date(event.start);
      var eventEnd = event.end ? new Date(event.end) : eventStart;
      
      // Normalize dates to midnight for comparison
      var dayStart = new Date(date.getFullYear(), date.getMonth(), date.getDate());
      var dayEnd = new Date(dayStart);
      dayEnd.setDate(dayEnd.getDate() + 1);
      
      return eventStart < dayEnd && eventEnd >= dayStart;
    });
  };

  Calendar.prototype.getEvents = function() {
    return this.events;
  };

  Calendar.prototype.addEvent = function(event) {
    this.events.push(event);
    this.render();
  };

  Calendar.prototype.removeEvent = function(eventId) {
    this.events = this.events.filter(function(e) { return e.id !== eventId; });
    this.render();
  };

  return {
    Calendar: Calendar
  };
})();
